import { prettyAction } from "../../src/utils/apl-parser/pretty-log";
import type { Action, Condition } from "../../src/utils/apl-parser/types";

function stripComment(line: string): string {
  const idx = line.indexOf("#");
  return (idx === -1 ? line : line.slice(0, idx)).trim();
}

function context(lines: string[], i: number, r = 2): string {
  return lines
    .slice(Math.max(0, i - r), i + r + 1)
    .map((l, k) => {
      const n = i - r + k;
      return `${n === i ? ">>" : "  "} ${n + 1} | ${l}`;
    })
    .join("\n");
}

/**
 * Your pretty-printer can produce explicit ParenExpr nodes ("kind":"paren").
 * Those are semantically irrelevant for the condition language (they're only grouping),
 * so for "semantic roundtrip" we erase them from the AST before comparing.
 */
function stripParensCondition(c: Condition): Condition {
  switch (c.kind) {
    case "paren":
      return stripParensCondition(c.expr);
    case "unary":
      return { ...c, expr: stripParensCondition(c.expr) };
    case "binary":
      return {
        ...c,
        left: stripParensCondition(c.left),
        right: stripParensCondition(c.right),
      };
    case "sequence":
    case "ident":
    case "number":
      return c;
    default: {
      const _never: never = c;
      return c;
    }
  }
}

function stripParensAction(a: Action): Action {
  return {
    ...a,
    segments: a.segments.map((s) => ({
      ...s,
      expr: stripParensCondition(s.expr),
    })),
  };
}

function parseOrThrow(line: string, fileLine: number): Action {
  const a = parseAction(line);
  if (!a) throw new Error(`parseAction returned null at line ${fileLine}`);
  return a;
}

function assertRoundtrip(lines: string[], filename: string) {
  const expectedLines: string[] = [];
  const fileLines: number[] = [];

  for (let i = 0; i < lines.length; i++) {
    const clean = stripComment(lines[i] ?? "");
    if (!clean) continue;
    expectedLines.push(clean);
    fileLines.push(i + 1);
  }

  for (let i = 0; i < expectedLines.length; i++) {
    const src = expectedLines[i];
    const lineNo = fileLines[i];

    // IMPORTANT: do NOT strip parens before printing
    const ast1Raw = parseOrThrow(src, lineNo);
    const printed = prettyAction(ast1Raw);
    const ast2Raw = parseOrThrow(printed, lineNo);

    const ast1 = stripParensAction(ast1Raw);
    const ast2 = stripParensAction(ast2Raw);

    // console.log(
    //   `[${filename}:${lineNo}]\n` +
    //   `INPUT:   ${src}\n` +
    //   `PRINTED: ${printed}\n`,
    // );

    try {
      expect(ast2).toEqual(ast1);
    } catch {
      throw new Error(
        `AST roundtrip mismatch in ${filename} at file line ${lineNo}:\n` +
        `INPUT:   ${src}\n` +
        `PRINTED: ${printed}\n\n` +
        `Context:\n${context(expectedLines, i)}`,
      );
    }
  }
}

test("parser pretty-print roundtrip simple (AST equality, ignore comments)", () => {
  const file = path.join("tests", "parser", "simple.simc");
  const raw = fs.readFileSync(file, "utf8").split(/\r?\n/);
  assertRoundtrip(raw, "simple.simc");
});

